/*
 * A064508  Prime numbers generated by casting a number in its own base.
 * https://oeis.org/A064508
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = the n‑th prime obtained by casting a number into its own
 *            base. (OEIS A064508)
 * Range:     u8 n <= 3, u16 n <= 8, u32 n <= 31, u64 n <= 31, u128 n <= 31,
 *            big any n
 * Helpers:   cast_value, isPrimeGeneric, seq_alloc, seq_realloc
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include <stdlib.h>

/* Utility headers (provided by the build system) */
#include "../utils/isPrimeGeneric.h"
#include "../utils/seq_alloc.h"
#include "../utils/seq_realloc.h"
#include "../utils/cast_value.h"

/* Static table of primes found so far and state for the search */
static seq_t *prime_vals   = NULL;   /* array of found prime values   */
static size_t prime_cap   = 0;       /* allocated capacity of array   */
static size_t prime_len   = 0;       /* number of primes stored       */
static idx_t  last_n_used = 0;       /* last integer n examined       */

/*--------------------------------------------------------------------
 * Ensure that at least `needed` primes are computed and stored.
 *--------------------------------------------------------------------*/
static void ensure_terms(idx_t needed)
{
    if (prime_len >= needed)
        return;

    /* Allocate the array on first use. */
    if (prime_vals == NULL) {
        prime_cap   = 64;
        prime_vals  = seq_alloc(prime_cap);   /* allocates `prime_cap` seq_t's */
        prime_len   = 0;
    }

    /* Search forward until we have at least `needed` primes. */
    while (prime_len < needed) {
        ++last_n_used;                      /* candidate integer n   */
        seq_t val;
        if (!cast_value(last_n_used, &val))
            continue;                       /* digit invalid        */
        if (isPrimeGeneric(val)) {          /* prime found          */
            /* Grow the array if necessary. */
            if (prime_len == prime_cap) {
                size_t new_cap = prime_cap * 2;
                seq_t *tmp = seq_realloc(prime_vals, prime_cap, new_cap);
                prime_vals = tmp;
                prime_cap  = new_cap;
            }
            prime_vals[prime_len++] = val;
        }
    }
}

/*--------------------------------------------------------------------
 * Main sequence function.
 *--------------------------------------------------------------------*/
seq_t a(idx_t n)
{
    if (n == 0)
        return 0;                          /* undefined for offset    */
    ensure_terms(n);
    return prime_vals[n - 1];
}
